import json, sys
new = [r for r in json.load(open("lib/target/benchmark-native.json"))["runs"] if r["engine"] == "native"]
old = {(r["case"], r["mode"]): r for r in json.load(open("lib/benchmark/results.json"))["runs"] if r["engine"] == "native"}
changed, grown, merged, fresh = [], [], [], []
for r in new:
    o = old.get((r["case"], r["mode"]))
    if o is None:
        fresh.append((r["case"], r["mode"], r["verdict"]))
        continue
    if r["verdict"] != o["verdict"]:
        changed.append((r["case"], r["mode"], o["verdict"], r["verdict"]))
    s, t = (o.get("solver") or {}), (r.get("solver") or {})
    if s.get("clauses") and t.get("clauses") and t["clauses"] > 1.10 * s["clauses"]:
        grown.append((r["case"], r["mode"], s["clauses"], t["clauses"]))
    if t.get("merges", 0) != s.get("merges", 0) or t.get("paths") != s.get("paths"):
        merged.append((r["case"], r["mode"], s.get("paths"), t.get("paths"), s.get("merges"), t.get("merges"), s.get("clauses"), t.get("clauses")))
print(f"own-checker runs: {len(new)}; new cases: {len(fresh)}; verdicts changed: {len(changed)}; formulas grown past 10%: {len(grown)}; paths or merges changed: {len(merged)}")
for f in fresh: print("  new:", *f)
for c in changed: print("  verdict changed:", *c)
for g in grown: print("  clauses grown:", *g)
for m in merged: print("  paths %s->%s merges %s->%s clauses %s->%s:" % m[2:], m[0], m[1])
sys.exit(1 if changed else 0)
